#include "UI/AlphaMenuHUD.h"
#include "Engine/Canvas.h"
#include "Engine/Engine.h"
#include "GameFramework/GameUserSettings.h"
#include "UI/AlphaMenuPlayerController.h"
void AAlphaMenuHUD::DrawButton(const FString& Label,FName Id,float X,float Y,float W,float H,bool bEnabled){DrawRect(bEnabled?FLinearColor(.08f,.07f,.055f,.9f):FLinearColor(.04f,.04f,.04f,.65f),X,Y,W,H);DrawText(Label,bEnabled?FLinearColor(.92f,.86f,.70f,1):FLinearColor(.4f,.4f,.4f,1),X+20,Y+14,GEngine->GetSmallFont(),1.05f,false);if(bEnabled)AddHitBox(FVector2D(X,Y),FVector2D(W,H),Id,true,10);}
void AAlphaMenuHUD::DrawHUD(){Super::DrawHUD();if(!Canvas||!GEngine)return;auto* PC=Cast<AAlphaMenuPlayerController>(PlayerOwner);if(!PC)return;DrawRect(FLinearColor(.012f,.014f,.018f,1),0,0,Canvas->SizeX,Canvas->SizeY);DrawText(TEXT("DARK ARISEN"),FLinearColor(.95f,.9f,.78f,1),96,72,GEngine->GetLargeFont(),1.45f,false);DrawText(TEXT("START-TO-CREDITS ALPHA"),FLinearColor(.58f,.58f,.58f,1),100,136,GEngine->GetSmallFont(),1,false);const float X=100,W=360,H=54;float Y=220;if(PC->MenuPage==EAlphaMenuPage::Main){DrawButton(TEXT("NEW GAME"),TEXT("NewGame"),X,Y,W,H);Y+=68;DrawButton(TEXT("CONTINUE"),TEXT("Continue"),X,Y,W,H,PC->HasContinueSave());Y+=68;DrawButton(TEXT("OPTIONS / SETTINGS"),TEXT("Settings"),X,Y,W,H);Y+=68;DrawButton(TEXT("QUIT"),TEXT("Quit"),X,Y,W,H);DrawText(TEXT("Esc/P Pause  |  M Map  |  N Minimap  |  F5 Save  |  F9 Load"),FLinearColor(.5f,.5f,.5f,1),100,Canvas->SizeY-64,GEngine->GetSmallFont(),.9f,false);}else{auto* S=UGameUserSettings::GetGameUserSettings();DrawText(TEXT("SETTINGS"),FLinearColor::White,X,Y-44,GEngine->GetLargeFont(),1,false);DrawButton(FString::Printf(TEXT("VSync: %s"),S&&S->IsVSyncEnabled()?TEXT("ON"):TEXT("OFF")),TEXT("VSync"),X,Y,W,H);Y+=68;DrawButton(TEXT("Graphics: LOW"),TEXT("Quality0"),X,Y,W,H);Y+=68;DrawButton(TEXT("Graphics: MEDIUM"),TEXT("Quality1"),X,Y,W,H);Y+=68;DrawButton(TEXT("Graphics: HIGH"),TEXT("Quality2"),X,Y,W,H);Y+=68;DrawButton(TEXT("Graphics: EPIC"),TEXT("Quality3"),X,Y,W,H);Y+=68;DrawButton(FString::Printf(TEXT("Display: %s"),S&&S->GetFullscreenMode()==EWindowMode::Windowed?TEXT("WINDOWED"):TEXT("FULLSCREEN")),TEXT("Fullscreen"),X,Y,W,H);Y+=68;DrawButton(TEXT("BACK"),TEXT("Back"),X,Y,W,H);}}
void AAlphaMenuHUD::NotifyHitBoxClick(FName Id){Super::NotifyHitBoxClick(Id);auto* PC=Cast<AAlphaMenuPlayerController>(PlayerOwner);if(!PC)return;if(Id==TEXT("NewGame"))PC->StartNewGame();else if(Id==TEXT("Continue"))PC->ContinueGame();else if(Id==TEXT("Settings"))PC->OpenSettings();else if(Id==TEXT("Quit"))PC->QuitGame();else if(Id==TEXT("VSync"))PC->ToggleVSync();else if(Id==TEXT("Fullscreen"))PC->ToggleFullscreen();else if(Id==TEXT("Quality0"))PC->SetQualityPreset(0);else if(Id==TEXT("Quality1"))PC->SetQualityPreset(1);else if(Id==TEXT("Quality2"))PC->SetQualityPreset(2);else if(Id==TEXT("Quality3"))PC->SetQualityPreset(3);else if(Id==TEXT("Back"))PC->BackToMain();}
